// Add the destination links here when the client supplies them.
const CORBAN_CONFIG = { shopUrl: '', contactEmail: '' };
const header=`<header><a href="index.html" aria-label="Corban home"><img class="logo" src="assets/logo.png" alt="Corban"></a><nav aria-label="Main navigation"><a href="about.html">About Corban</a><a href="contact.html">Contact</a><button class="cart" aria-label="Open shopping cart"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4"><path d="M3 3h2l3 12h11l2-9H6M9 20h.01M18 20h.01" stroke-linecap="round"/><circle cx="9" cy="20" r="1"/><circle cx="18" cy="20" r="1"/></svg><span>Cart</span></button></nav></header>`;
const footer=`<footer><div class="footer-top"><a href="index.html" aria-label="Corban home"><img class="logo" src="assets/logo.png" alt="Corban"></a><nav aria-label="Footer navigation"><a href="about.html">About Corban</a><a href="contact.html">Contact</a><a href="index.html">Back to the movement ↗</a></nav></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Corban</span><span>A life of purpose. An everyday offering.</span></div></footer>`;
document.querySelector('[data-header]').outerHTML=header;document.querySelector('[data-footer]').outerHTML=footer;
document.querySelectorAll('nav a').forEach(a=>{if(a.getAttribute('href')===location.pathname.split('/').pop())a.setAttribute('aria-current','page')});
const dialog=document.createElement('dialog');dialog.innerHTML='<h2>The next chapter is coming.</h2><p>The Corban shop will be linked here soon. Explore the movement while we get everything ready.</p><button class="solid">Keep exploring</button>';document.body.append(dialog);dialog.querySelector('button').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});document.querySelector('.cart').onclick=()=>CORBAN_CONFIG.shopUrl?location.assign(CORBAN_CONFIG.shopUrl):dialog.showModal();
const form=document.querySelector('form');if(form)form.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(form);if(CORBAN_CONFIG.contactEmail){location.href='mailto:'+CORBAN_CONFIG.contactEmail+'?subject='+encodeURIComponent(data.get('topic')+' — '+data.get('name'))+'&body='+encodeURIComponent(data.get('message')+'\n\n'+data.get('email'));}else{document.querySelector('.status').textContent='The contact channel is being set up. This form is a preview and your message has not been sent.';}});
